import{_ as a,a as t,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 142 Someone invited Sally ... Sally was invited ...","description":"学习 一般过去时被动语态，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 142 Someone invited Sally ... Sally was invited ...","description":"学习 一般过去时被动语态，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 一般过去时被动语态，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 141 Sally's first train ride","link":"/life/english/new-concept/book-1/unit-06/lesson-141"},"next":{"text":"第一册：英语初阶 · Lesson 143 A walk through the woods","link":"/life/english/new-concept/book-1/unit-06/lesson-143"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 141 Sally's first train ride","link":"/life/english/new-concept/book-1/unit-06/lesson-141"},"next":{"text":"第一册：英语初阶 · Lesson 143 A walk through the woods","link":"/life/english/new-concept/book-1/unit-06/lesson-143"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-142.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-142.md"}`),l={name:"life/english/new-concept/book-1/unit-06/lesson-142.md"};function s(o,e,r,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-142-someone-invited-sally-sally-was-invited" tabindex="-1">第一册：英语初阶 · Lesson 142 Someone invited Sally ... Sally was invited ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-142-someone-invited-sally-sally-was-invited" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 142 Someone invited Sally ... Sally was invited ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-141">配套课 Lesson 141</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>把注意力从执行者转向事件对象 本课要掌握一般过去时被动语态，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>invite</td><td>/ɪnˈvaɪt/</td><td>v.</td><td>邀请</td><td>invite a friend</td></tr><tr><td>journey</td><td>/ˈdʒɜːni/</td><td>n.</td><td>旅程</td><td>a long journey</td></tr><tr><td>passenger</td><td>/ˈpæsɪndʒə/</td><td>n.</td><td>乘客</td><td>train passengers</td></tr><tr><td>build</td><td>/bɪld/</td><td>v.</td><td>建造</td><td>build a bridge</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>was invited — 过去被邀请</li><li>were built — 多个对象过去被建造</li></ul><h2 id="语法讲解-一般过去时被动语态" tabindex="-1">语法讲解：一般过去时被动语态 <a class="header-anchor" href="#语法讲解-一般过去时被动语态" aria-label="Permalink to &quot;语法讲解：一般过去时被动语态&quot;">​</a></h2><p>被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>This bridge was built fifty years ago.</p></blockquote><p>这座桥建于五十年前。</p><p>This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>by email 表方式，不是执行者；被动中的 built 是分词，不是 build 原形。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“This bridge was built fifty years ago.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>This bridge was built fifty years ago. The guests were invited by email.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“把注意力从执行者转向事件对象”写两至三句，再读给同伴听。至少使用一次一般过去时被动语态，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。 The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填分词：The bridge was ___ (build) in 1970.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> built</p><p><strong>解析：</strong> 按本课规则判断：被动语态由 be + 过去分词构成，时态与主谓一致体现在 be 上。一般过去时用 was/were + 分词。只有及物动词及可接受的及物结构通常能转被动，happen 不可机械写 was happened。执行者不重要或未知时，可以省略引出执行者的 by 短语；如 by the host 中 the host 是执行者。by 也可表示方式，如本课 by email 表示通过电子邮件，不能把所有 by 短语都理解为执行者。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这座桥建于五十年前。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> This bridge was built fifty years ago.</p><p><strong>解析：</strong> This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The guests were invited by email.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 客人们是通过电子邮件受邀的。</p><p><strong>解析：</strong> The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般过去时被动语态。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-141">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-143">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(l,[["render",s]]);export{p as __pageData,u as default};
